import {ecoPanel,arrivalPanel,arrivalRows,ecoComparison,attachEco,ecoText,signalPanel,fuelPanel} from './eco-ui.js';
import {createAdvanced} from './advanced-ui.js';
import {quality,setQualityConfig} from './quality.js';
import {nodes,trainDefs,incidentDefs,makeWorld,step,action,metrics,eta,replay,targetBlock,incidentFor,trigger} from './corridor-engine.js';
import {corridorScene} from './corridor-scene.js';
const $=s=>document.querySelector(s);let lang=Number(localStorage.getItem('jol-lang')||0),dark=localStorage.getItem('jol-theme')!=='light';const t=(a,b)=>lang?b:a,txt=a=>a[lang];
const clock=m=>{if(m===null||m===undefined)return '—';const n=480+Math.floor(m);return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`};
const grade=d=>d<=5?'good':d<=15?'warn':'bad';const round=n=>Math.round(n);const icon=k=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${({cube:'<path d="m12 2 9 5v10l-9 5-9-5V7zM3 7l9 5 9-5M12 12v10"/>',chart:'<path d="M4 3v17h17M8 15v-5M13 15V5M18 15V8"/>',game:'<rect x="3" y="6" width="18" height="13" rx="4"/><path d="M7 12h6M10 9v6M17 11h.01M18 14h.01"/>',scenario:'<path d="M3 7h18M3 17h18M8 3v8M16 13v8"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',play:'<path d="m8 4 12 8-12 8z"/>',pause:'<path d="M8 4v16M16 4v16"/>',reset:'<path d="M4 9a8 8 0 1 1 0 7M4 3v6h6"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1 1M18 18l1 1"/>',alert:'<path d="m12 3 10 18H2zM12 9v5M12 17h.01"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',train:'<rect x="5" y="3" width="14" height="15" rx="3"/><path d="M5 10h14M8 14h.01M16 14h.01M8 18l-2 3M16 18l2 3"/>'})[k]||''}</svg>`;
let page='map',world=makeWorld({eco:true,mode:'wave',events:false}),game=makeWorld({eco:true}),before=makeWorld({scenario:0}),after=makeWorld({scenario:0,auto:true});let selected='SIM-FRT-208',selectedBlock=null,scenario=0,playing=false,speed=4,compareTime=0,showResult=false,sceneA=null,sceneB=null,last=performance.now(),paintElapsed=0,reasonFilter='all';let selectedStation=null,modalFocus=null,advancedElapsed=0;
const advanced=createAdvanced({configure:c=>{setQualityConfig(c);[world,game,before,after].forEach(w=>w.config=c);},playing:()=>playing,lang:()=>lang,page:()=>page,world:()=>world,replace:w=>{world=w;},selected:()=>selected,select:id=>{selected=id;sceneA?.select(id);paint();},pause:()=>{playing=false;},render:()=>render(),paint:()=>paint(),diagram:w=>routeDiagram(w),stats:w=>stats(w),clock});
const live=()=>page==='game'?game:['ato','history','plan','system','dashboard'].includes(page)?advanced.analysis():advanced.display(world);const currentIncident=w=>selectedBlock!==null?incidentFor(w,selectedBlock):[...w.incidents].reverse().find(e=>e.until>w.time);const statusNames={running:['В движении','Қозғалыста'],queue:['Ждёт путь','Жол күтуде'],blocked:['Перед закрытым сигналом','Жабық сигнал алдында'],held:['Удержан диспетчером','Диспетчер ұстады'],ready:['Готов к отправлению','Жөнелуге дайын'],done:['Прибыл','Келді']};
const stateName=tr=>txt(statusNames[tr.state]||statusNames.ready);
const navs=[['map','cube',['3D-коридор','3D-дәліз']],['scenario','scenario',['Сценарии · до / после','Сценарий · бұрын / кейін']],['game','game',['Управлять движением','Қозғалысты басқару']],['plan','chart',['Поездограмма и план','Пойыз кестесі / жоспар']],['ato','train',['Eco-driving / скорость','Eco-driving / жылдамдық']],['history','reset',['История и отчёты','Тарих және есептер']],['system','info',['Данные и API','Деректер және API']],['dashboard','chart',['Аналитика','Аналитика']],['causes','alert',['Причины задержек','Кешігу себептері']],['about','info',['Как это работает','Қалай жұмыс істейді']]];
function route(){const p=location.hash.slice(1).split('/');page=navs.some(n=>n[0]===p[0])?p[0]:'map';if(page==='scenario'){const next=Math.max(0,Math.min(3,+p[1]||0));if(next!==scenario){scenario=next;resetCompare();}}}
function go(s){if(location.hash==='#'+s){route();render()}else location.hash=s;}
function resetCompare(){before=makeWorld({scenario});after=makeWorld({scenario,auto:true});compareTime=0;}
function stat(label,value,unit='',color=''){return `<div class="stat"><div class="label">${label}</div><div class="value ${color}">${value}<small>${unit}</small></div></div>`;}
function stats(w){const m=metrics(w);return stat(t('На маршруте','Маршрутта'),6-m.finished,'/ 6')+stat(t('Ждут освобождения','Босауын күтуде'),m.waiting,'',m.waiting?'warn':'good')+stat(t('Суммарная задержка','Жалпы кешігу'),round(m.total),t('мин','мин'),grade(m.avg))+stat(t('Индекс движения','Қозғалыс индексі'),m.index,'/100',quality(w).level)+stat(t('Прибыли','Келді'),m.finished,'/6');}
function render(){sceneA?.dispose();sceneB?.dispose();sceneA=sceneB=null;document.body.classList.toggle('light',!dark);document.documentElement.lang=lang?'kk':'ru';const title=txt(navs.find(n=>n[0]===page)[2]);
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#map"><img src="/jibekjoly/logo.svg" alt=""><div><strong>JibekJoly</strong></div></a><div class="navlabel">${t('Цифровая железная дорога','Цифрлық теміржол')}</div><nav>${navs.map(([id,ic,name])=>`<a class="navlink ${page===id?'active':''}" href="#${id}${id==='scenario'?'/'+scenario:''}" ${page===id?'aria-current="page"':''}>${icon(ic)}${txt(name)}</a>`).join('')}</nav><div class="sidebar-bottom"><strong>Көкшетау → Алматы</strong><div class="mini-route">9 ${t('станций','станция')} · 6 ${t('поездов','пойыз')}</div><p style="font-size:11px;margin-top:12px;color:var(--accent)">${t('Весь маршрут в одной модели','Бүкіл маршрут бір модельде')}</p><small>${t('Сжатый масштаб · учебные данные','Сығылған масштаб · оқу деректері')}</small></div></aside><section class="workspace"><header class="topbar"><div class="crumb"><strong>${title}</strong><span>/</span><span>${t('Весь коридор','Бүкіл дәліз')}</span></div><div class="top-controls"><span class="demo">${t('СИМУЛЯЦИЯ','СИМУЛЯЦИЯ')}</span><div class="clock" id="header-clock">${clock(page==='scenario'?compareTime:live().time)}</div><div class="lang"><button data-act="lang" data-value="0" class="${lang?'':'active'}">RU</button><button data-act="lang" data-value="1" class="${lang?'active':''}">KZ</button></div><button class="small ghost" data-act="theme" aria-label="${t('Сменить тему','Тақырыпты ауыстыру')}">${icon('sun')}</button></div></header><main class="content">${advanced.strip()}${['plan','ato','history','system'].includes(page)?`<div id="advanced-content">${advanced.page(page)}</div>`:page==='scenario'?scenarioPage():page==='about'?aboutPage():page==='dashboard'?dashboardPage()+`<div id="dashboard-overview">${advanced.overview()}</div>`:page==='causes'?causesPage():controlPage()}<footer class="footer"><span>JibekJoly · ${t('Цифровой коридор','Цифрлық дәліз')}</span><span>${t('Учебная топология маршрута. Масштаб, времена и пути условные. Не подключено к КТЖ.','Маршруттың оқу топологиясы. Масштаб, уақыт және жолдар шартты. ҚТЖ-ға қосылмаған.')}</span></footer>${lang?`<p class="translation-note">${ecoText('translation',lang)}</p>`:''}</main></section></div>`;
 if(['map','game'].includes(page)&&(page!=='game'||!showResult)){sceneA=mountScene('world',live());}if(page==='scenario'){sceneA=mountScene('before-world',before,true);sceneB=mountScene('after-world',after,true);}paint();advanced.mount();}
function mountScene(id,w,compact=false){const host=document.getElementById(id);if(!host)return null;const s=corridorScene(host,{lang,dark,compact,onTrain:id=>selectTrain(id),onBlock:i=>selectBlock(i),onStation:i=>stationModal(i),onSignal:(i,dir)=>{if(page==='scenario'||advanced.isReplay())return;action(live(),'signal',null,i,dir);paint(true);}});s.update(w);s.select(selected);return s;}
function title(h,sub,extra=''){return `<div class="page-heading"><div><div class="eyebrow">${t('Көкшетау · Астана · Алматы','Көкшетау · Астана · Алматы')}</div><h1>${h}</h1><p>${sub}</p></div>${extra}</div>`;}
function controls(compare=false){return `<div class="transport"><button class="primary" data-act="play" id="play-button">${icon(playing?'pause':'play')} ${playing?t('Пауза','Кідіріс'):t('Запустить движение','Қозғалысты бастау')}</button><button data-act="reset" aria-label="${t('Сначала','Басынан')}">${icon('reset')}</button><span class="transport-clock" id="transport-clock">${clock(compare?compareTime:live().time)}</span><label class="speed-label">${t('Скорость','Жылдамдық')} <select id="speed">${[1,2,4,8].map(n=>`<option value="${n}" ${n===speed?'selected':''}>${n}×</option>`).join('')}</select></label>${compare?`<div class="jump-buttons"><button data-act="seek" data-time="5">${t('До сбоя','Ақауға дейін')}</button><button data-act="seek" data-time="8">${t('Сбой','Ақау')}</button><button data-act="seek" data-time="35">${t('Последствия','Салдары')}</button><button data-act="seek" data-time="180">${t('Итог','Қорытынды')}</button></div>`:`<div class="jump-buttons"><button data-act="incident">${icon('alert')} ${t('Следующий сбой','Келесі ақау')}</button>${page==='map'?`<button data-act="finish-trip">${ecoText('tripFinish',lang)}</button>`:''}${page==='game'?`<button data-act="finish-game">${t('Завершить смену','Ауысымды аяқтау')}</button>`:''}</div>`}</div>`;}
function worldPanel(id,caption='',compare=false){return `<section class="panel world-panel">${caption?`<div class="panel-head"><h2>${caption}</h2><span class="pill">6 ${t('поездов','пойыз')}</span></div>`:''}<div class="world-stage ${compare?'compact':''}"><div class="world-host" id="${id}"></div>${!compare?`<div class="world-heading"><span class="pill">3D · ${t('ВЕСЬ МАРШРУТ','БҮКІЛ МАРШРУТ')}</span><small>${t('Перетаскивайте для вращения · колёсико для масштаба','Бұру үшін сүйреңіз · масштаб үшін дөңгелек')}</small></div>`:''}<div class="world-views"><button data-act="camera" data-view="overview" data-scene="${id}">${t('Весь маршрут','Бүкіл маршрут')}</button><button data-act="camera" data-view="top" data-scene="${id}">${t('Сверху','Үстінен')}</button><button data-act="camera" data-view="side" data-scene="${id}">3D</button></div></div><div class="world-key"><span><i style="background:var(--accent)"></i>${t('Свободно / резерв','Бос / резерв')}</span><span><i style="background:var(--blue)"></i>${t('Занято поездом','Пойыз бар')}</span><span><i style="background:var(--amber)"></i>40 ${t('км/ч','км/сағ')}</span><span><i style="background:var(--red)"></i>${t('Закрыто','Жабық')}</span><span>${t('Задержки: зелёный ≤5 · жёлтый 6–15 · красный >15 мин','Кешігу: жасыл ≤5 · сары 6–15 · қызыл >15 мин')}</span></div></section>`;}
function controlPage(){if(page==='game'&&showResult)return resultPage();const w=live();return title(page==='game'?t('Диспетчерская в ваших руках','Диспетчерлік сіздің қолыңызда'):t('Весь путь — перед вами','Бүкіл жол — алдыңызда'),page==='game'?t('Сбой останавливает симуляцию. Выберите поезд, путь и действие — затем продолжите движение.','Ақау симуляцияны тоқтатады. Пойызды, жолды және әрекетті таңдаңыз — кейін қозғалысты жалғастырыңыз.'):t('Шесть поездов, девять станций, одна непрерывная 3D-модель.','Алты пойыз, тоғыз станция, бір үздіксіз 3D-модель.'),page==='map'?`<a class="button-link" href="#game">${icon('game')} ${t('Взять управление','Басқаруды алу')}</a>`:'')+`<div class="stats corridor-stats" id="live-stats">${stats(w)}</div>${controls()}${page==='map'?`<div class="wave-mode"><label>${ecoText('mode',lang)} <select id="wave-mode"><option value="wave" ${w.mode==='wave'?'selected':''}>${ecoText('wave',lang)}</option><option value="crowded" ${w.mode!=='wave'?'selected':''}>${ecoText('crowded',lang)}</option></select></label><p class="meta">${w.mode==='wave'?ecoText('waveNote',lang):ecoText('packageNote',lang)}</p></div>`:''}<div id="incident-banner">${incidentBanner(w)}</div>${worldPanel('world')}<div class="train-ribbon" id="train-ribbon">${trainRibbon(w)}</div><div id="fuel-result">${fuelPanel(w,lang)}</div><div class="eco-grid"><div id="eco-card">${ecoPanel(w,selected,lang,advanced.isReplay())}</div><div id="station-board">${arrivalPanel(w,selectedStation??4,lang)}</div></div><div id="signal-board">${signalPanel(w,lang,advanced.isReplay())}</div><section class="panel route-panel"><div class="panel-head"><h2>${t('Живая схема всего пути','Бүкіл жолдың тірі сызбасы')}</h2><small>${t('Нажмите на участок для управления','Басқару үшін учаскені басыңыз')}</small></div><div class="route-diagram" id="route-diagram">${routeDiagram(w)}</div></section><div class="operator-grid"><section class="panel"><div class="panel-head"><h2>${t('Пульт диспетчера','Диспетчер пульті')}</h2><span class="pill good">${t('Ручное управление','Қолмен басқару')}</span></div><div class="panel-body" id="command-panel">${commandPanel(w)}</div></section><section class="panel"><div class="panel-head"><h2>${t('Очередь и прогноз','Кезек және болжам')}</h2><span class="pill">${t('В реальном времени модели','Модель уақытында')}</span></div><div id="queue-panel">${queuePanel(w)}</div></section><section class="panel"><div class="panel-head"><h2>${t('Журнал действий','Әрекеттер журналы')}</h2><span class="pill" id="action-count">${w.actions}</span></div><div class="log-feed" id="log-panel">${logPanel(w)}</div></section></div><section class="panel" style="margin-top:18px"><div class="panel-head"><h2>${t('Все шесть поездов — план и факт','Барлық алты пойыз — жоспар және нақты')}</h2></div><div id="train-table">${trainTable(w)}</div></section>`;}
function trainRibbon(w){return w.trains.map(tr=>`<button class="train-chip ${selected===tr.id?'selected':''}" data-act="train" data-id="${tr.id}" style="--train:${tr.color}"><span class="train-id"><i></i>${tr.id}${tr.type===2&&w.eco?'<em class="freight-mark">ECO</em>':''}</span><b class="${grade(tr.delay)}">+${round(tr.delay)}′</b><small>${stateName(tr)}</small></button>`).join('');}
function incidentBanner(w){const inc=currentIncident(w);const unresolved=[...w.incidents].reverse().find(e=>!e.managed&&e.until>w.time);if(!inc&&!unresolved)return `<div class="calm-banner">${icon('check')}${t('Выберите поезд или участок. Следующее событие появится во время движения.','Пойызды немесе учаскені таңдаңыз. Келесі оқиға қозғалыс кезінде пайда болады.')}<span>${w.triggered.length}/4 ${t('событий','оқиға')}</span></div>`;const e=unresolved||inc;return `<div class="live-incident"><div>${icon('alert')}</div><div><b>${txt(e.title)}</b><p>${nodes[e.block].name} — ${nodes[e.block+1].name} · ${e.type==='closure'?t('основной путь закрыт','негізгі жол жабық'):t('ограничение 40 км/ч','40 км/сағ шектеуі')} · ${t('снятие в','аяқталуы')} ${clock(e.until)} ${e.repair?'· '+t('бригада работает','бригада жұмыс істейді'):''}</p></div><button data-act="block" data-id="${e.block}">${t('Выбрать участок','Учаскені таңдау')}</button></div>`;}
function commandPanel(w){const tr=w.trains.find(v=>v.id===selected),n=selectedBlock??Math.max(0,Math.min(7,targetBlock(tr))),e=incidentFor(w,n),block=w.blocks[n];return `<div class="command-selected"><span class="eyebrow">${t('Выбранный поезд','Таңдалған пойыз')}</span><div class="row between"><b style="color:${tr.color}">${tr.id}</b><span class="pill ${grade(tr.delay)}">+${round(tr.delay)} ${t('мин','мин')}</span></div><p>${txt(tr.name)}</p><div class="row between"><small>${stateName(tr)}</small><button class="small" data-act="follow">${t('Следовать камерой','Камерамен ілесу')}</button></div></div><label class="block-select-label">${t('Управляемый участок','Басқарылатын учаске')}<select id="block-select"><option value="auto" ${selectedBlock===null?'selected':''}>${t('По положению поезда','Пойыз орны бойынша')}</option>${w.blocks.map(b=>`<option value="${b.i}" ${selectedBlock===b.i?'selected':''}>${nodes[b.i].name} — ${nodes[b.i+1].name}</option>`).join('')}</select></label><div class="command-buttons"><button data-act="priority" ${tr.finished!==null?'disabled':''}>${icon('train')}${t('Приоритет поезду','Пойызға басымдық')}</button><button data-act="hold" ${tr.finished!==null?'disabled':''}>${icon(tr.hold?'play':'pause')}${tr.hold?t('Отпустить поезд','Пойызды жіберу'):t('Удержать на станции','Станцияда ұстау')}</button>${w.mode==='wave'?'':`<button data-act="reserve" ${block.reserveOpen?'disabled':''}>${icon('scenario')}${block.reserveOpen?(w.mode==='wave'?ecoText('wave',lang):t('Резерв открыт','Резерв ашық')):t('Открыть резервный путь','Резервтік жолды ашу')}</button>`}<button data-act="repair" ${!e||e.repair?'disabled':''}>${icon('reset')}${e?.repair?t('Бригада в работе','Бригада жұмыс істейді'):t('Ускорить ремонт · 6 мин','Жөндеуді жеделдету · 6 мин')}</button></div><div class="command-hint">${t('Приоритет действует на следующем участке. Удержание — на ближайшей станции. Поезд не проходит закрытый сигнал; резерв пропускает один состав за раз.','Басымдық келесі учаскеде қолданылады. Ұстау — ең жақын станцияда. Пойыз жабық сигналдан өтпейді; резерв бір уақытта бір құрамды өткізеді.')}</div>${e?`<button class="wait-button" data-act="wait">${t('Ничего не менять · ждать освобождения','Ештеңе өзгертпеу · босауын күту')}</button>`:''}<div id="command-feedback" role="status"></div>`;}
function queuePanel(w){const tr=w.trains.find(t=>t.id===selected),n=selectedBlock??Math.max(0,Math.min(7,targetBlock(tr))),b=w.blocks[n],queue=w.trains.filter(t=>t.finished===null&&targetBlock(t)===n);return `<div class="queue-title"><strong>${nodes[n].name} — ${nodes[n+1].name}</strong><small>${t('Основной путь','Негізгі жол')}: ${b.main||t('свободен','бос')}<br>${t('Резерв','Резерв')}: ${b.reserveOpen?(b.reserve||t('свободен','бос')):t('закрыт','жабық')}${b.preferred?'<br>'+t('Следующий приоритет','Келесі басымдық')+': '+b.preferred:''}</small></div>${queue.length?queue.map(v=>`<button class="queue-train" data-act="train" data-id="${v.id}"><span><b style="color:${v.color}">${v.id}</b><small>${stateName(v)}</small></span><span class="${grade(v.delay)}">+${round(v.delay)}′<small>${t('финиш','мәре')} ~${clock(eta(w,v))}</small></span></button>`).join(''):`<div class="empty">${t('Сейчас на подходе нет поездов','Қазір жақындаған пойыз жоқ')}</div>`}<p class="queue-foot">${t('Прогноз учитывает оставшийся путь и известные ограничения. Новые события могут его изменить.','Болжам қалған жол мен белгілі шектеулерді ескереді. Жаңа оқиғалар оны өзгерте алады.')}</p>`;}
function logText(l){const names={signal:ecoText('signalLog',lang),eco:ecoText('ecoLog',lang),start:t('Шесть поездов готовы. Коридор открыт.','Алты пойыз дайын. Дәліз ашық.'),repair:t('Отправлена ремонтная бригада. Ожидание не более 6 мин.','Жөндеу бригадасы жіберілді. Күту 6 минуттан аспайды.'),reserve:t('Открыт резервный путь.','Резервтік жол ашылды.'),priority:t('Приоритет на следующем участке','Келесі учаскеде басымдық'),hold:t('Удержание на ближайшей станции','Ең жақын станцияда ұстау'),release:t('Поезд отпущен','Пойыз жіберілді'),wait:t('Выбрано ожидание освобождения','Босауын күту таңдалды'),clear:t('Ограничение снято','Шектеу алынды'),enter:t('Вход на участок','Учаскеге кіру'),finish:t('Прибыл на конечную станцию','Соңғы станцияға келді'),incident:l.index!==undefined?txt(incidentDefs[l.index].title):''};return `${l.id?l.id+' · ':''}${names[l.key]||''}${l.lane==='reserve'?' · '+t('через резерв','резерв арқылы'):''}`;}
function logPanel(w){return w.log.slice(0,12).map(l=>`<div class="log-entry ${l.kind}"><time>${clock(l.time)}</time><div>${logText(l)}${l.block!==undefined?`<small>${nodes[l.block].name} — ${nodes[l.block+1].name}</small>`:''}</div></div>`).join('');}
function trainTable(w){return `<div class="table-wrap"><table><thead><tr><th>${t('Поезд','Пойыз')}</th><th>${t('Положение','Орны')}</th><th>${t('Статус','Күйі')}</th><th>${t('План финиша','Мәре жоспары')}</th><th>${t('Прогноз / факт','Болжам / нақты')}</th><th>${t('Задержка','Кешігу')}</th><th>${t('Пройдено','Өтті')}</th></tr></thead><tbody>${w.trains.map(tr=>`<tr class="clickable ${tr.id===selected?'selected-row':''}" data-act="train" data-id="${tr.id}" tabindex="0"><td><b style="color:${tr.color}">${tr.id}</b></td><td>${tr.segment===null?nodes[tr.node].name:nodes[tr.segment].name+' — '+nodes[tr.segment+1].name}</td><td>${stateName(tr)}</td><td>${clock(tr.plan)}</td><td>${tr.finished===null?'~':''}${clock(eta(w,tr))}</td><td class="${grade(tr.delay)}">+${round(tr.delay)}′</td><td><div class="progress" style="width:75px"><i style="width:${Math.min(100,tr.work/tr.plan*100)}%;background:${tr.color}"></i></div></td></tr>`).join('')}</tbody></table></div>`;}
function routeDiagram(w){const width=1000,X=i=>45+i*113;return `<svg viewBox="0 0 1000 115" role="img" aria-label="${t('Состояние всех участков маршрута','Барлық маршрут учаскелерінің күйі')}">${w.blocks.map((b,i)=>{const e=incidentFor(w,i),color=e?.type==='closure'?'var(--red)':e?'var(--amber)':b.main?'var(--blue)':'var(--accent)';return `<g role="button" tabindex="0" data-act="block" data-id="${i}" aria-label="${nodes[i].name} — ${nodes[i+1].name}"><line x1="${X(i)}" x2="${X(i+1)}" y1="49" y2="49" stroke="${color}" stroke-width="5"/><line x1="${X(i)}" x2="${X(i+1)}" y1="65" y2="65" stroke="${b.reserveOpen?'var(--accent)':'var(--line)'}" stroke-width="3" stroke-dasharray="4 4"/><rect x="${X(i)}" y="24" width="113" height="50" fill="transparent"/>${e?`<text x="${(X(i)+X(i+1))/2}" y="24" text-anchor="middle" fill="${color}">${e.type==='closure'?'×':'40'}</text>`:''}</g>`}).join('')}${nodes.map((n,i)=>`<g><circle cx="${X(i)}" cy="49" r="6" fill="var(--panel)" stroke="var(--muted)" stroke-width="2"/><text x="${X(i)}" y="95" text-anchor="middle" fill="var(--muted)">${n.name}</text></g>`).join('')}${w.trains.map((tr,i)=>{const p=tr.segment===null?tr.node:tr.segment+tr.p;return `<g role="button" tabindex="0" data-act="train" data-id="${tr.id}"><rect x="${X(p)-7}" y="${tr.dir===1?34:53}" width="14" height="9" rx="2" fill="${tr.color}"/><title>${tr.id} +${round(tr.delay)} ${t('мин','мин')}</title></g>`}).join('')}</svg>`;}
function chart(series,labels=null){const W=700,H=225,L=50,B=32,T=18;const max=Math.max(10,...series.flatMap(s=>s.data.map(p=>p.y))),maxX=Math.max(1,...series.flatMap(s=>s.data.map(p=>p.x)));const X=x=>L+x/maxX*(W-L-15),Y=y=>H-B-y/max*(H-B-T);return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${t('Динамика задержек','Кешігу динамикасы')}">${[0,.25,.5,.75,1].map(f=>`<line class="gridline" x1="${L}" x2="${W-15}" y1="${Y(f*max)}" y2="${Y(f*max)}"/><text x="${L-8}" y="${Y(f*max)+4}" text-anchor="end">${round(f*max)}</text><text x="${X(f*maxX)}" y="${H-8}" text-anchor="middle">${round(f*maxX)}′</text>`).join('')}${series.map(s=>`<polyline points="${s.data.map(p=>X(p.x)+','+Y(p.y)).join(' ')}" stroke="${s.color}" stroke-width="3" fill="none"/>`).join('')}</svg>`;}
function scenarioPage(){const d=incidentDefs[scenario];return title(t('Один сбой. Два живых маршрута.','Бір ақау. Екі тірі маршрут.'),t('Слева — ожидание по базовому плану. Справа — ремонт и резерв через минуту после события.','Сол жақта — базалық жоспар бойынша күту. Оң жақта — оқиғадан бір минут кейін жөндеу мен резерв.'))+`<div class="tabs">${incidentDefs.map((d,i)=>`<button data-act="scenario" data-id="${i}" class="${i===scenario?'active':''}">${i+1}. ${txt(d.title)}</button>`).join('')}</div><div class="scenario-banner">${icon('alert')}<div><h2>${txt(d.title)}</h2><p>${txt(d.description)} ${t('В этом отдельном сценарии событие начинается на 6-й минуте.','Бұл жеке сценарийде оқиға 6-минутта басталады.')}</p></div></div>${controls(true)}<div class="compare-worlds">${worldPanel('before-world',t('Без вмешательства','Араласусыз'),true)}${worldPanel('after-world',t('С управлением','Басқарумен'),true)}</div><div class="compare-metrics" id="compare-metrics">${compareMetrics()}</div><div id="eco-compare">${ecoComparison(before,after,lang)}</div><div class="compare-route"><div id="before-route">${routeDiagram(before)}</div><div id="after-route">${routeDiagram(after)}</div></div><div class="simulation-controls"><span>${t('Время','Уақыт')}</span><input id="compare-slider" type="range" min="0" max="180" value="${compareTime}" step=".5" aria-label="${t('Время сравнения','Салыстыру уақыты')}"><span>180 ${t('мин модели','модель минуты')}</span></div><div class="grid2 equal"><section class="panel"><div class="panel-head"><h2>${t('Задержки по всему маршруту','Бүкіл маршруттағы кешігулер')}</h2><div class="legend"><span><i class="line-key red"></i>${t('Без действий','Әрекетсіз')}</span><span><i class="line-key"></i>${t('С управлением','Басқарумен')}</span></div></div><div id="compare-chart" class="chart-wrap">${compareChart()}</div><p class="gantt-note">${t('По горизонтали — модельные минуты; по вертикали — сумма задержек всех шести поездов.','Көлденең — модель минуттары; тігінен — алты пойыздың кешігу қосындысы.')}</p></section><section class="panel"><div class="panel-head"><h2>${t('Что изменилось на маршруте','Маршрутта не өзгерді')}</h2></div><div class="log-feed" id="compare-log">${logPanel(after)}</div></section></div><section class="panel"><div class="panel-head"><h2>${t('Шесть поездов: одинаковые условия, разный результат','Алты пойыз: бірдей жағдай, әртүрлі нәтиже')}</h2></div><div id="compare-table">${compareTable()}</div></section><div class="info">${t('Здесь не подставлены готовые проценты: обе модели независимо рассчитывают занятость путей, очередь и движение. Кнопки камеры меняют ракурс; ползунок пересчитывает обе модели с начала.','Мұнда дайын пайыздар қойылмаған: екі модель де жолдардың бос болуын, кезекті және қозғалысты бөлек есептейді. Камера түймелері көріністі өзгертеді; жүгірткі екі модельді де басынан қайта есептейді.')}</div>`;}
function compareMetrics(){const a=metrics(before),b=metrics(after);return [a,b].map((m,i)=>`<div class="mini-metrics"><div><small>${t('Сумма задержек','Кешігу қосындысы')}</small><b class="${i?'good':'bad'}">${round(m.total)}′</b></div><div><small>${t('В очереди','Кезекте')}</small><b>${m.waiting}</b></div><div><small>${t('Прибыли','Келді')}</small><b>${m.finished}/6</b></div><div><small>${t('Индекс','Индекс')}</small><b>${m.index}</b></div></div>`).join('');}
function compareChart(){return chart([{color:'var(--red)',data:before.history.map(p=>({x:p.time,y:p.total}))},{color:'var(--accent)',data:after.history.map(p=>({x:p.time,y:p.total}))}]);}
function compareTable(){return `<div class="table-wrap"><table><thead><tr><th>${t('Поезд','Пойыз')}</th><th>${t('Без действий','Әрекетсіз')}</th><th>${t('С управлением','Басқарумен')}</th><th>${t('Разница задержки','Кешігу айырмасы')}</th><th>${t('Прогноз с управлением','Басқарумен болжам')}</th></tr></thead><tbody>${before.trains.map((tr,i)=>{const alt=after.trains[i],diff=alt.delay-tr.delay;return `<tr><td><b style="color:${tr.color}">${tr.id}</b></td><td>+${round(tr.delay)}′</td><td>+${round(alt.delay)}′</td><td class="${diff<=0?'good':'bad'}">${diff>0?'+':''}${round(diff)}′</td><td>${alt.finished===null?'~':''}${clock(eta(after,alt))}</td></tr>`}).join('')}</tbody></table></div>`;}
function dashboardPage(){const world=advanced.analysis(),m=metrics(world);return advanced.tripToolbar()+title(t('Видеть причину, а не только опоздание','Тек кешігуді емес, себебін көру'),t('Графики используют запись выбранной поездки. Повторный запуск не нужен.','Графиктер таңдалған сапар жазбасын пайдаланады. Қайта бастау қажет емес.'))+`<div class="stats corridor-stats" id="live-stats">${stats(world)}</div><div class="grid2 equal"><section class="panel"><div class="panel-head"><h2>${t('Как растут задержки','Кешігулер қалай өседі')}</h2><a href="#map">${t('Вернуться в 3D','3D-ге оралу')}</a></div><div id="dashboard-chart" class="chart-wrap">${chart([{color:'var(--accent)',data:advanced.delaySeries()}])}</div></section><section class="panel"><div class="panel-head"><h2>${t('Загрузка участков сейчас','Учаскелердің қазіргі жүктемесі')}</h2></div><div class="panel-body" id="block-load">${blockLoad(world)}</div></section></div><section class="panel"><div class="panel-head"><h2>${t('План и прогноз по шести поездам','Алты пойыздың жоспары мен болжамы')}</h2></div><div id="train-table">${trainTable(world)}</div></section><div class="info">${t('Индекс объединяет пять факторов; их веса и формула показаны в разделе «Поездограмма и план». Это учебный показатель. Точные значения приведены в минутах и пассажиро-минутах.','Индекс бес факторды біріктіреді; олардың салмақтары мен формуласы «Пойыз кестесі / жоспар» бөлімінде көрсетілген. Бұл оқу көрсеткіші. Нақты мәндер минутпен және жолаушы-минутпен берілген.')}</div>`;}
function blockLoad(w){return w.blocks.map(b=>{const e=incidentFor(w,b.i);return `<div class="load-row"><span>${nodes[b.i].name} — ${nodes[b.i+1].name}</span><span class="pill ${e?'bad':b.main?'warn':'good'}">${e?(e.type==='closure'?t('Закрыт','Жабық'):'40 '+t('км/ч','км/сағ')):b.main||t('Свободен','Бос')}</span></div>`}).join('');}
function causesPage(){const rows=world.trains.filter(tr=>reasonFilter==='all'||(reasonFilter==='waiting'?tr.wait>0:tr.state==='blocked'));return title(t('Откуда появилась задержка','Кешігу қайдан пайда болды'),t('Накопленное ожидание и текущее состояние шести поездов','Алты пойыздың жиналған күтуі мен қазіргі күйі'))+`<div class="filters"><label>${t('Показать','Көрсету')} <select id="reason-filter"><option value="all">${t('Все поезда','Барлық пойыздар')}</option><option value="waiting" ${reasonFilter==='waiting'?'selected':''}>${t('С накопленным ожиданием','Жиналған күтуі бар')}</option><option value="blocked" ${reasonFilter==='blocked'?'selected':''}>${t('Перед закрытым сигналом','Жабық сигнал алдында')}</option></select></label></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>${t('Поезд','Пойыз')}</th><th>${t('Полное опоздание','Толық кешігу')}</th><th>${t('Ожидание без движения','Қозғалыссыз күту')}</th><th>${t('Текущее состояние','Қазіргі күйі')}</th></tr></thead><tbody>${rows.map(tr=>`<tr><td style="color:${tr.color}">${tr.id}</td><td>+${round(tr.delay)}′</td><td>${round(tr.wait)}′</td><td>${stateName(tr)}</td></tr>`).join('')}</tbody></table>${!rows.length?`<div class="empty">${t('Нет поездов по выбранному условию','Таңдалған шарт бойынша пойыздар жоқ')}</div>`:''}</div></section><div class="grid2 equal" style="margin-top:18px"><section class="panel"><div class="panel-head"><h2>${t('Рейтинг по опозданию','Кешігу бойынша рейтинг')}</h2></div><div class="panel-body">${[...rows].sort((a,b)=>b.delay-a.delay).map(tr=>`<div class="bar-row"><b>${tr.id}</b><div class="bar"><i style="width:${tr.delay/Math.max(1,...rows.map(v=>v.delay))*100}%;background:${tr.color}"></i></div><span>+${round(tr.delay)}′</span></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>${t('Ограничения и действия','Шектеулер мен әрекеттер')}</h2></div><div class="log-feed">${world.log.filter(l=>l.kind!=='move').slice(0,14).map(l=>`<div class="log-entry ${l.kind}"><time>${clock(l.time)}</time><div>${logText(l)}</div></div>`).join('')}</div></section></div>`;}
function resultPage(){const baseline=replay(180),automatic=replay(180,{auto:true}),m=metrics(game),bm=metrics(baseline),am=metrics(automatic),cost=m.weighted+(6-m.finished)*60,ref=am.weighted+(6-am.finished)*60,score=Math.round(100*(m.finished/6)*Math.min(1,Math.max(1,ref)/Math.max(1,cost)));return title(t('Ваша смена: решения и последствия','Сіздің ауысым: шешімдер мен салдарлар'),t('Результат рассчитан по фактическому движению. Все действия сохранены в журнале.','Нәтиже нақты модель қозғалысы бойынша есептелді. Барлық әрекеттер журналда сақталған.'),`<button class="primary" data-act="new-game">${t('Новая смена','Жаңа ауысым')}</button>`)+`<div class="result-hero"><div><div class="eyebrow">${t('Диспетчерский результат','Диспетчер нәтижесі')}</div><h1>${m.finished===6?t('Все шесть поездов прибыли','Барлық алты пойыз келді'):t(`Прибыли ${m.finished} из 6 поездов`,`6 пойыздың ${m.finished}-і келді`)}</h1><p>${t('Оценка сравнивает вашу взвешенную задержку с автоматической политикой «ремонт + резерв». За каждый не прибывший поезд добавляется 60 условных единиц. Оценка также умножается на долю прибывших поездов. Это не доказанный оптимум.','Баға сіздің өлшенген кешігуіңізді «жөндеу + резерв» автоматты саясатымен салыстырады. Келмеген әр пойызға 60 шартты бірлік қосылады. Баға келген пойыздар үлесіне де көбейтіледі. Бұл дәлелденген оптимум емес.')}</p><span class="pill">${game.actions} ${t('действий','әрекет')} · ${clock(game.time)}</span></div><div class="big-score">${score}<small style="font-size:17px">/100</small></div></div><div class="stats corridor-stats">${stats(game)}</div><div class="grid2 equal"><section class="panel"><div class="panel-head"><h2>${t('Цена решений на всём маршруте','Бүкіл маршруттағы шешімдер құны')}</h2><div class="legend"><span><i class="line-key red"></i>${t('Без действий','Әрекетсіз')}</span><span><i class="line-key"></i>${t('Ваш путь','Сіздің жол')}</span></div></div><div class="chart-wrap">${chart([{color:'var(--red)',data:baseline.history.map(p=>({x:p.time,y:p.total}))},{color:'var(--accent)',data:game.history.map(p=>({x:p.time,y:p.total}))}])}</div><p class="gantt-note">${t('Базовый прогон — до 180 минут или прибытия всех поездов. Ваш прогон заканчивается в момент завершения смены.','Базалық прогон — 180 минутқа дейін немесе барлық пойыз келгенше. Сіздің прогон ауысым аяқталған кезде тоқтайды.')}</p></section><section class="panel"><div class="panel-head"><h2>${t('Что вы сделали','Сіз не істедіңіз')}</h2></div><div class="log-feed">${game.log.filter(l=>l.kind==='action').map(l=>`<div class="log-entry action"><time>${clock(l.time)}</time><div>${logText(l)}</div></div>`).join('')||`<div class="empty">${t('Действий не было','Әрекет болған жоқ')}</div>`}</div></section></div><section class="panel"><div class="panel-head"><h2>${t('Итог по каждому поезду','Әр пойыздың нәтижесі')}</h2></div>${trainTable(game)}</section>`;}
function aboutPage(){return title(t('Как устроена цифровая модель','Цифрлық модель қалай құрылған'),t('Что реально рассчитывается и где проходит граница демонстрации','Не нақты есептеледі және демонстрацияның шегі қайда'))+`<div class="about-grid"><section class="panel"><div class="panel-body prose"><h2>${t('Весь коридор, а не отдельные станции','Жеке станциялар емес, бүкіл дәліз')}</h2><p>${t('Шесть поездов движутся по одной непрерывной модели из девяти станций и восьми перегонов. Положение каждого поезда, занятость пути, прогноз прибытия и задержка связаны с одним расчётом.','Алты пойыз тоғыз станция мен сегіз аралықтан тұратын бір үздіксіз модельде қозғалады. Әр пойыздың орны, жолдың бос болуы, келу болжамы және кешігуі бір есеппен байланысты.')}</p><p>${t('Имена станций задают коридор Көкшетау — Астана — Алматы. Это сжатая топологическая схема: промежуточные станции показаны выборочно, расстояния, число путей и времена условные. Это не точная географическая или инженерная модель и не 2ГИС.','Станция атаулары Көкшетау — Астана — Алматы дәлізін береді. Бұл сығылған топологиялық сызба: аралық станциялар іріктелген, қашықтықтар, жол саны мен уақыт шартты. Бұл дәл географиялық немесе инженерлік модель және 2ГИС емес.')}</p><h2>${t('Движение и ограничения','Қозғалыс және шектеулер')}</h2><p>${t('На одном основном пути перегона находится не больше одного поезда. Следующий состав допускается через одну модельную минуту после освобождения. На станциях поезда могут разъехаться. Резерв — отдельный путь с собственной занятостью и скоростью 80% от обычной.','Бір аралықтың негізгі жолында бір пойыздан артық болмайды. Келесі құрам жол босағаннан кейін бір модель минутынан соң өтеді. Станцияларда пойыздар айрыла алады. Резерв — жеке босау есебі бар, қалыпты жылдамдықтың 80%-ымен жүретін бөлек жол.')}</p><p>${t('Закрытие сигнала останавливает движение по основному пути. Ремонт сокращает оставшееся ограничение до шести минут, но не снимает его мгновенно. Ограничение скорости действует до окончания срока. Удержание применяется на ближайшей станции. Приоритет не разрешает проезд через занятый или закрытый путь.','Сигнал жабылса, негізгі жолдағы қозғалыс тоқтайды. Жөндеу шектеудің қалған уақытын алты минутқа қысқартады, бірақ оны бірден алмайды. Жылдамдық шектеуі мерзімі біткенше сақталады. Ұстау ең жақын станцияда қолданылады. Басымдық бос емес немесе жабық жолдан өтуге рұқсат бермейді.')}</p><h2>${t('Задержка, прогноз и оценка','Кешігу, болжам және баға')}</h2><p>${t('Текущая задержка — время с начала минус нормативное время уже пройденной части пути. После прибытия она фиксируется. Прогноз продолжает копию текущего состояния с той же очередью, скоростями и известными ограничениями. Неизвестные будущие события в прогноз не включены.','Қазіргі кешігу — басталғаннан бергі уақыт минус өткен жолдың нормативтік уақыты. Келгеннен кейін ол бекітіледі. Болжам ағымдағы күй көшірмесін сол кезек, жылдамдық және белгілі шектеулермен жалғастырады. Белгісіз болашақ оқиғалар болжамға кірмейді.')}</p><p>${t('Индекс — взвешенная сумма пяти факторов: пунктуальность, пропускная способность, энергия, конфликты и точность прибытия. Формула и веса доступны в разделе «Поездограмма и план». Взвешенная задержка использует веса 3 для скоростного, 2 для пассажирского, 1 для грузового. Все коэффициенты демонстрационные. Это детерминированная симуляция, а не обученная нейросеть.','Индекс — бес фактордың салмақталған қосындысы: уақтылық, өткізу қабілеті, энергия, қақтығыстар және келу дәлдігі. Формула мен салмақтар «Пойыз кестесі / жоспар» бөлімінде. Өлшенген кешігу жүрдекке 3, жолаушыға 2, жүкке 1 салмақтарын қолданады. Барлық коэффициенттер демонстрациялық. Бұл детерминдік симуляция, үйретілген нейрожелі емес.')}</p><h2>${t('Сценарии и игра','Сценарийлер мен ойын')}</h2><p>${t('В сценариях два независимых прогона получают одинаковое событие на шестой минуте. Справа автоматическая политика через минуту отправляет ремонт и открывает резерв. В игре события возникают последовательно; четвёртое выбирает участок действующего поезда. Ваши действия меняют очередь и последующие задержки.','Сценарийлерде екі тәуелсіз прогон алтыншы минутта бірдей оқиғаны алады. Оң жақта автоматты саясат бір минуттан кейін жөндеуді жіберіп, резервті ашады. Ойында оқиғалар кезекпен пайда болады; төртіншісі қозғалыстағы пойыз учаскесін таңдайды. Сіздің әрекеттеріңіз кезекті және кейінгі кешігулерді өзгертеді.')}</p><div class="info">${t('Учебный прототип не управляет реальной железной дорогой. Для внедрения необходимы достоверная топология, регламенты, реальные расписания и проверка специалистами.','Оқу прототипі нақты теміржолды басқармайды. Енгізу үшін сенімді топология, регламенттер, нақты кестелер және мамандар тексеруі қажет.')}</div></div></section><div><section class="panel"><div class="panel-head"><h2>${t('Панели управления','Басқару панельдері')}</h2></div><div class="panel-body arch"><div><b>01 · ${t('Общий 3D-коридор','Жалпы 3D-дәліз')}</b><small>${t('Положение, сигнал, задержка и резервные пути','Орын, сигнал, кешігу және резервтік жолдар')}</small></div><div><b>02 · ${t('Пульт диспетчера','Диспетчер пульті')}</b><small>${t('Приоритет, удержание, резерв и ремонт','Басымдық, ұстау, резерв және жөндеу')}</small></div><div><b>03 · ${t('Живая схема и очередь','Тірі сызба мен кезек')}</b><small>${t('Весь маршрут виден даже без поддержки 3D','3D болмаса да бүкіл маршрут көрінеді')}</small></div><div><b>04 · ${t('Прогноз и журнал','Болжам және журнал')}</b><small>${t('Что изменилось после каждого действия','Әр әрекеттен кейін не өзгерді')}</small></div></div></section><section class="panel" style="margin-top:18px"><div class="panel-body prose"><h2>${t('Как показать за минуту','Бір минутта қалай көрсетуге болады')}</h2><p>${t('Откройте игру. Нажмите «Запустить движение». При первом сбое выберите красный участок, отправьте ремонтную бригаду и откройте резерв. Наблюдайте, как очередь снова начинает двигаться. Затем откройте сценарий и нажмите «Последствия».','Ойынды ашыңыз. «Қозғалысты бастау» түймесін басыңыз. Бірінші ақауда қызыл учаскені таңдап, жөндеу бригадасын жіберіңіз және резервті ашыңыз. Кезектің қайта қозғалуын бақылаңыз. Кейін сценарийді ашып, «Салдары» түймесін басыңыз.')}</p><p class="meta">Three.js · ${ecoText('dataLead',lang)}</p></div></section></div></div>`;}
function selectTrain(id){selected=id;sceneA?.select(id);sceneB?.select(id);if(page==='scenario'){const a=before.trains.find(t=>t.id===id),b=after.trains.find(t=>t.id===id);openModal(id,`<div class="detail-grid"><div><small>${t('Без действий','Әрекетсіз')}</small><strong class="bad">+${round(a.delay)}′</strong><p>${stateName(a)}</p></div><div><small>${t('С управлением','Басқарумен')}</small><strong class="good">+${round(b.delay)}′</strong><p>${stateName(b)}</p></div></div>`);}else paint(true);}
function selectBlock(i){selectedBlock=i;if(page==='scenario'){openModal(nodes[i].name+' — '+nodes[i+1].name,`<p>${t('Без вмешательства','Араласусыз')}: ${before.blocks[i].main||t('нет поезда','пойыз жоқ')}</p><p>${t('С управлением','Басқарумен')}: ${after.blocks[i].main||t('нет поезда','пойыз жоқ')}</p><div class="info">${t('Резерв в управляемом сценарии','Басқарылатын сценарийдегі резерв')}: ${after.blocks[i].reserveOpen?t('открыт','ашық'):t('закрыт','жабық')}</div>`);}else{paint(true);$('#command-panel')?.scrollIntoView({behavior:'smooth',block:'nearest'});}}
function stationModal(i){selectedStation=i;const w=page==='scenario'?after:live();openModal(nodes[i].name,`<div id="station-modal-board">${arrivalRows(w,i,lang).replaceAll('data-act="train"','data-act="modal-train"')}</div>`);paint();}
function openModal(title,body){modalFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header><h2 id="modal-title">${title}</h2><button data-act="close" aria-label="${t('Закрыть','Жабу')}">${icon('close')}</button></header><div class="panel-body">${body}</div></section></div>`;$('#modal-root button')?.focus();}
function closeModal(){$('#modal-root').innerHTML='';modalFocus?.focus?.();}
function setPlay(){for(const el of document.querySelectorAll('[data-global-transport]')){el.disabled=world.done;el.textContent=world.done?t('Поездка завершена','Сапар аяқталды'):playing?t('Пауза текущей поездки','Ағымдағы сапарды кідірту'):t('Продолжить текущую поездку','Ағымдағы сапарды жалғастыру');}const b=$('#play-button');if(b)b.innerHTML=icon(playing?'pause':'play')+' '+(playing?t('Пауза','Кідіріс'):t('Запустить движение','Қозғалысты бастау'));}
function paint(force=false){const w=live();const mb=document.getElementById('station-modal-board');if(mb&&selectedStation!==null&&!mb.contains(document.activeElement))mb.innerHTML=arrivalRows(page==='scenario'?after:w,selectedStation,lang).replaceAll('data-act="train"','data-act="modal-train"');if($('#header-clock'))$('#header-clock').textContent=clock(page==='scenario'?compareTime:w.time);if($('#transport-clock'))$('#transport-clock').textContent=clock(page==='scenario'?compareTime:w.time);setPlay();
 if(['map','game'].includes(page)&&!(page==='game'&&showResult)){sceneA?.update(w);sceneA?.select(selected);const entries={'live-stats':()=>stats(w),'incident-banner':()=>incidentBanner(w),'train-ribbon':()=>trainRibbon(w),'route-diagram':()=>routeDiagram(w),'queue-panel':()=>queuePanel(w),'log-panel':()=>logPanel(w),'train-table':()=>trainTable(w),'eco-card':()=>ecoPanel(w,selected,lang,advanced.isReplay()),'station-board':()=>arrivalPanel(w,selectedStation??4,lang),'signal-board':()=>signalPanel(w,lang,advanced.isReplay()),'fuel-result':()=>fuelPanel(w,lang)};for(const [id,fn]of Object.entries(entries)){const el=document.getElementById(id);if(el){const active=el.contains(document.activeElement)?document.activeElement:null;const aid=active?.dataset?.id,adir=active?.dataset?.dir,act=active?.dataset?.act,eco=active?.dataset?.eco,focusId=active?.id;if(active?.matches('select'))continue;el.innerHTML=fn();if(eco)el.querySelector(`[data-eco="${eco}"]`)?.focus({preventScroll:true});if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});if(aid&&act)el.querySelector(`[data-act="${act}"][data-id="${aid}"]${adir?`[data-dir="${adir}"]`:""}`)?.focus({preventScroll:true});}}const cp=$('#command-panel');if(cp&&(force||!cp.contains(document.activeElement)))cp.innerHTML=commandPanel(w);if($('#action-count'))$('#action-count').textContent=w.actions;}
 if(page==='dashboard'){const d=advanced.analysis();const update={'live-stats':()=>stats(d),'dashboard-chart':()=>chart([{color:'var(--accent)',data:advanced.delaySeries()}]),'block-load':()=>blockLoad(d),'train-table':()=>trainTable(d),'dashboard-overview':()=>advanced.overview()};for(const [id,fn]of Object.entries(update)){const el=document.getElementById(id);if(el)el.innerHTML=fn();}}
 if(page==='scenario'){sceneA?.update(before);sceneB?.update(after);const es={'eco-compare':()=>ecoComparison(before,after,lang),'compare-metrics':compareMetrics,'compare-chart':compareChart,'compare-table':compareTable,'compare-log':()=>logPanel(after),'before-route':()=>routeDiagram(before),'after-route':()=>routeDiagram(after)};for(const [id,fn]of Object.entries(es)){if(document.getElementById(id))document.getElementById(id).innerHTML=fn();}if($('#compare-slider')&&document.activeElement!==$('#compare-slider'))$('#compare-slider').value=compareTime;}}
function restart(){playing=false;if(page==='scenario')resetCompare();else if(page==='game'){game=makeWorld({eco:true});showResult=false;}else world=makeWorld({eco:true,mode:world.mode,events:world.mode!=='wave'});selectedBlock=null;render();}
async function doCommand(kind){const w=live(),tr=w.trains.find(t=>t.id===selected),n=selectedBlock??Math.max(0,Math.min(7,targetBlock(tr)));if(await advanced.command(kind,selected,n))return;const ok=action(w,kind,selected,n);if(ok){paint(true);const el=$('#command-feedback');if(el){el.innerHTML=`<div class="success-message">${t('Команда принята. Нажмите «Запустить движение», чтобы увидеть результат.','Пәрмен қабылданды. Нәтижені көру үшін «Қозғалысты бастау» түймесін басыңыз.')}</div>`;}}}
async function jumpToIncident(){if(await advanced.command('incident'))return;const w=live();playing=false;if(w.triggered.length>=4||w.done)return;if(!w.events){const e=trigger(w,w.triggered.length,w.time);if(e)selectedBlock=e.block;paint(true);return;}const target=w.triggered.length+1;let guard=0;while(w.triggered.length<target&&!w.done&&w.time<180&&guard++<2500)step(w,.05);const e=w.incidents.at(-1);if(e)selectedBlock=e.block;paint(true);}
async function handle(act,el){advanced.measure(performance.now());switch(act){case'signal':if(advanced.isReplay()||live().done)return;action(live(),'signal',null,+el.dataset.id,+el.dataset.dir);paint(true);break;case'finish-trip':playing=false;step(live(),240);paint(true);document.getElementById('fuel-result')?.scrollIntoView({behavior:'smooth',block:'center'});break;case'lang':lang=+el.dataset.value;localStorage.setItem('jol-lang',lang);closeModal();render();break;case'theme':dark=!dark;localStorage.setItem('jol-theme',dark?'dark':'light');render();break;case'play':if(page!=='game'&&page!=='scenario'&&advanced.isReplay())advanced.resumeCurrent();if(page!=='game'&&page!=='scenario'&&(advanced.isRemote()||advanced.isReplay())){await advanced.command(playing?'pause':'play');playing=!playing;setPlay();break;}if((page==='game'&&game.done)||(page==='map'&&world.done)||(page==='scenario'&&compareTime>=180)){restart();}playing=!playing;setPlay();break;case'reset':if(page!=='game'&&page!=='scenario'&&await advanced.command('reset'))break;if(page==='game'&&game.time>0){openModal(t('Начать смену заново?','Ауысымды қайта бастау керек пе?'),`<p>${t('Тек текущая игровая сессия будет сброшена.','Тек осы ойын сессиясы тазарады.')}</p><button class="primary" data-act="reset-confirm" style="margin-top:18px">${t('Начать заново','Қайта бастау')}</button>`);}else restart();break;case'reset-confirm':closeModal();restart();break;case'new-game':restart();break;case'train':selectTrain(el.dataset.id);break;case'block':selectBlock(+el.dataset.id);break;case'follow':sceneA?.follow(selected);break;case'camera':{const sc=el.dataset.scene==='after-world'?sceneB:sceneA;sc?.view(el.dataset.view);break;}case'priority':case'hold':case'reserve':case'repair':case'wait':doCommand(act);break;case'incident':jumpToIncident();break;case'scenario':playing=false;scenario=+el.dataset.id;resetCompare();go('scenario/'+scenario);break;case'seek':playing=false;compareTime=+el.dataset.time;before=replay(compareTime,{scenario});after=replay(compareTime,{scenario,auto:true});paint(true);break;case'finish-game':playing=false;openModal(t('Завершить эту смену?','Осы ауысымды аяқтау керек пе?'),`<p>${t('Не прибывшие поезда останутся незавершёнными и снизят оценку. Можно продолжить движение и закончить маршрут.','Келмеген пойыздар аяқталмаған болып, бағаны төмендетеді. Қозғалысты жалғастырып, маршрутты аяқтауға болады.')}</p><div class="row" style="margin-top:18px"><button class="primary" data-act="result">${t('Показать результат','Нәтижені көрсету')}</button><button data-act="close">${t('Продолжить','Жалғастыру')}</button></div>`);break;case'result':closeModal();showResult=true;render();break;case'close':closeModal();break;case'modal-train':closeModal();selectTrain(el.dataset.id);break;}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-act]');if(el&&!el.disabled)handle(el.dataset.act,el);if(e.target.classList.contains('modal-backdrop'))closeModal();});
document.addEventListener('change',e=>{if(e.target.id==='wave-mode'){playing=false;world=makeWorld({eco:true,mode:e.target.value,events:e.target.value!=='wave'});selectedBlock=null;render();}if(e.target.id==='eco-station'){selectedStation=+e.target.value;paint(true);}if(e.target.id==='speed')speed=+e.target.value;if(e.target.id==='block-select'){selectedBlock=e.target.value==='auto'?null:+e.target.value;paint(true);}if(e.target.id==='reason-filter'){reasonFilter=e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='compare-slider'){playing=false;compareTime=+e.target.value;before=replay(compareTime,{scenario});after=replay(compareTime,{scenario,auto:true});paint();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-act]:not(button):not(a)')){e.preventDefault();handle(e.target.dataset.act,e.target);}if(e.key==='Tab'&&$('.modal')){const els=[...$('.modal').querySelectorAll('button,a,input,select,[tabindex="0"]')];if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0]?.focus();}}});
function animate(now){const dt=Math.min(.15,(now-last)/1000);last=now;paintElapsed+=dt;advancedElapsed+=dt;if(playing){if(page==='scenario'){compareTime=Math.min(180,compareTime+dt*speed);step(before,dt*speed);step(after,dt*speed);sceneA?.update(before);sceneB?.update(after);if(compareTime>=180||before.done&&after.done){playing=false;paint();}}else if(page==='game'||!advanced.isRemote()){const w=page==='game'?game:world,events=step(w,dt*speed);sceneA?.update(live());if(page==='game'&&events.length){playing=false;selectedBlock=events.at(-1).block;paint(true);}if(w.done||w.time>=180){playing=false;if(page==='game'){showResult=true;render();}else paint();}}if(paintElapsed>.2){paintElapsed=0;paint();}}
 if(advancedElapsed>.25){advanced.tick();advancedElapsed=0;}requestAnimationFrame(animate);}
window.addEventListener('hashchange',()=>{const previous=page;route();if(['game','scenario'].includes(previous)||['game','scenario'].includes(page))playing=false;render();window.scrollTo(0,0)});route();render();requestAnimationFrame(animate);

attachEco({canEdit:()=>['ato','system'].includes(page)?advanced.canEdit():page==='game'||!advanced.isReplay(),world:()=>page==='scenario'?after:live(),lang:()=>lang,paint:()=>{paint(true);advanced.refresh();},pause:()=>{playing=false;setPlay();}});
